import argparse
import csv
import json


def read_rows(path):
    try:
        with open(path, newline="", encoding="utf-8-sig") as fh:
            reader = csv.reader(fh)
            rows = [r for r in reader]
    except FileNotFoundError:
        return []
    if not rows:
        return []
    header = [c.strip().lower() for c in rows[0]]
    out = []
    for raw in rows[1:]:
        if not raw or all((c or "").strip() == "" for c in raw):
            continue
        rec = {}
        for i, name in enumerate(header):
            rec[name] = raw[i] if i < len(raw) else ""
        out.append(rec)
    return out


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    orders_path = args["orders_path"]
    customers_path = args["customers_path"]

    west = set()
    for rec in read_rows(customers_path):
        cid = (rec.get("customer_id") or "").strip()
        region = (rec.get("region") or "").strip().lower()
        if cid and region == "west":
            west.add(cid)

    total = 0.0
    for rec in read_rows(orders_path):
        cid = (rec.get("customer_id") or "").strip()
        if cid not in west:
            continue
        amt = (rec.get("amount") or "").strip().replace(",", "")
        if not amt:
            continue
        try:
            total += float(amt)
        except ValueError:
            continue

    rounded = round(total, 10)
    if abs(rounded - round(rounded)) < 1e-9:
        print(int(round(rounded)))
    else:
        print(f"{rounded:.2f}")


main()

import argparse
import json
import csv
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(token):
    if token is None:
        return None
    s = str(token).strip()
    if not s:
        return None
    negative = False
    if s.startswith("(") and s.endswith(")"):
        negative = True
        s = s[1:-1].strip()
    cleaned = ""
    for ch in s:
        if ch in "$, \t\u00a0":
            continue
        cleaned += ch
    if cleaned.startswith("+"):
        cleaned = cleaned[1:]
    elif cleaned.startswith("-"):
        negative = not negative
        cleaned = cleaned[1:]
    if not cleaned:
        return None
    try:
        value = Decimal(cleaned)
    except InvalidOperation:
        return None
    return -value if negative else value


def find_amount_key(fieldnames):
    if not fieldnames:
        return None
    for name in fieldnames:
        if name is not None and name.strip().lower() == "amount":
            return name
    return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    opts = json.loads(args.payload)
    path = opts["path"]

    total = Decimal("0")
    with open(path, "r", newline="", encoding="utf-8-sig") as handle:
        reader = csv.DictReader(handle)
        key = find_amount_key(reader.fieldnames)
        if key is not None:
            for row in reader:
                value = parse_amount(row.get(key))
                if value is not None:
                    total += value

    print(total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


main()

import argparse
import json


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    path = args["path"]

    start = (8, 0, 0)
    end = (8, 30, 0)

    count = 0
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            fields = line.split()
            if len(fields) < 2:
                continue
            if fields[1] != "ERROR":
                continue
            parts = fields[0].split(":")
            if len(parts) != 3:
                continue
            try:
                stamp = (int(parts[0]), int(parts[1]), int(parts[2]))
            except ValueError:
                continue
            if start <= stamp < end:
                count += 1

    print(count)


main()

import argparse
import json


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    path = args["path"]

    best = {}  # user -> (ts, action)
    with open(path, "r", encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except ValueError:
                continue
            if not isinstance(rec, dict):
                continue
            user = rec.get("user")
            action = rec.get("action")
            ts = rec.get("ts")
            if user is None or action is None:
                continue
            if not isinstance(ts, (int, float)) or isinstance(ts, bool):
                continue
            prev = best.get(user)
            if prev is None or ts > prev[0]:
                best[user] = (ts, action)

    count = 0
    for ts, action in best.values():
        if action == "logout":
            count += 1
    print(count)


main()

import argparse
import csv
import json
from datetime import date


def parse_day(text):
    text = (text or "").strip()
    if len(text) != 10 or text[4] != "-" or text[7] != "-":
        return None
    y, m, d = text[0:4], text[5:7], text[8:10]
    if not (y.isdigit() and m.isdigit() and d.isdigit()):
        return None
    try:
        return date(int(y), int(m), int(d))
    except ValueError:
        return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    path = args["path"]

    days = []
    with open(path, "r", encoding="utf-8-sig", newline="") as fh:
        reader = csv.DictReader(fh)
        field = None
        for name in (reader.fieldnames or []):
            if name is not None and name.strip().lower() == "date":
                field = name
                break
        if field is not None:
            for row in reader:
                value = parse_day(row.get(field))
                if value is not None:
                    days.append(value)

    if len(days) < 2:
        print(0)
    else:
        print((max(days) - min(days)).days)


main()

import argparse
import csv
import json
from decimal import Decimal, InvalidOperation


def read_rows(path):
    with open(path, newline="", encoding="utf-8-sig") as fh:
        reader = csv.DictReader(fh)
        for raw in reader:
            row = {}
            for key, value in raw.items():
                if key is None:
                    continue
                row[key.strip().lower()] = value
            yield row


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    orders_path = args["orders_path"]
    customers_path = args["customers_path"]

    west = set()
    for row in read_rows(customers_path):
        cid = row.get("customer_id")
        region = row.get("region")
        if cid is None or region is None:
            continue
        if region.strip().lower() == "west":
            west.add(cid.strip())

    total = Decimal("0")
    for row in read_rows(orders_path):
        cid = row.get("customer_id")
        amount = row.get("amount")
        if cid is None or amount is None:
            continue
        if cid.strip() not in west:
            continue
        text = amount.strip()
        if not text:
            continue
        try:
            total += Decimal(text)
        except InvalidOperation:
            continue

    if total == total.to_integral_value():
        print(int(total))
    else:
        print(total.normalize())


main()

import argparse
import csv
import json
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(raw):
    if raw is None:
        return None
    t = raw.strip()
    if not t:
        return None
    neg = False
    if t.startswith("(") and t.endswith(")"):
        neg = True
        t = t[1:-1].strip()
    t = t.replace("$", "").replace(",", "").replace(" ", "")
    if t.startswith("-"):
        neg = not neg
        t = t[1:]
    elif t.startswith("+"):
        t = t[1:]
    if not t:
        return None
    # only plain decimal digits with at most one dot are acceptable
    if not t.replace(".", "", 1).isdigit():
        return None
    try:
        value = Decimal(t)
    except InvalidOperation:
        return None
    return -value if neg else value


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    path = args["path"]

    with open(path, "r", newline="", encoding="utf-8-sig", errors="replace") as handle:
        rows = list(csv.reader(handle))

    total = Decimal(0)
    if rows:
        header = rows[0]
        idx = None
        for i, name in enumerate(header):
            if name.strip().lower() == "amount":
                idx = i
                break
        if idx is not None:
            for row in rows[1:]:
                if idx < len(row):
                    value = parse_amount(row[idx])
                    if value is not None:
                        total += value

    print(str(total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)))


main()

